    if (
      typeof body.code !== "string" ||
      typeof body.code_verifier !== "string" ||
      typeof body.client_id !== "string" ||
      typeof body.redirect_uri !== "string"
    )
      throw new GatewayError(
        400,
        "invalid_request_error",
        "code, code_verifier, client_id, and redirect_uri are required.",
        "invalid_public_token_request",
      );
    if (
      !/^[A-Za-z0-9._~-]{43,128}$/.test(body.code_verifier) ||
      body.code.length > 512 ||
      body.client_id.length > 2_048 ||
      body.redirect_uri.length > 2_048
