function normalizeOrigin(value: string): string {
  const origin = new URL(value).origin;
  const host = new URL(origin).hostname;
  if (host === "twyne.love" || host === "www.twyne.love") {
    return "https://www.twyne.love";
  }
  return origin;
}

function isLoopbackOrigin(value: string): boolean {
  const host = new URL(value).hostname;
  return (
    host === "localhost" ||
    host === "127.0.0.1" ||
    host === "::1" ||
    host === "[::1]"
  );
}

function trustedOrigins(origin: string): string[] {
  const origins = new Set<string>([origin]);
  if (isLoopbackOrigin(origin)) {
    const url = new URL(origin);
    const port = url.port ? `:${url.port}` : "";
    // ATProto OAuth must return to an IP-literal loopback URI (RFC 8252),
    // while Vite commonly starts at localhost. Trust both representations of
    // the same local development service so the callback can use 127.0.0.1.
    origins.add(`http://localhost${port}`);
    origins.add(`http://127.0.0.1${port}`);
  }
  if (isTwyneProductionOrigin(origin)) {
    for (const prodOrigin of TWYNE_PRODUCTION_ORIGINS) {
      origins.add(prodOrigin);
    }
  }
  for (const raw of (process.env.TRUSTED_ORIGINS ?? "").split(",")) {
    const trimmed = raw.trim();
    if (!trimmed) continue;
    const normalized = normalizeOrigin(trimmed);
    origins.add(normalized);
    if (
      isTwyneProductionOrigin(trimmed) ||
      isTwyneProductionOrigin(normalized)
    ) {
      for (const prodOrigin of TWYNE_PRODUCTION_ORIGINS) {
        origins.add(prodOrigin);
      }
    }
  }
  return [...origins];
}

function isTwyneProductionOrigin(value: string): boolean {
  try {
    return TWYNE_PRODUCTION_ORIGINS.includes(
      new URL(value).origin as (typeof TWYNE_PRODUCTION_ORIGINS)[number],
    );
  } catch {
    return false;
  }
}

import { createDpopKeyPair, createDpopFetch } from "./notorganic";

/** Redeem a one-time provider authorization; no caller-supplied DID is trusted. */
export async function redeemProviderLink(
  input: { code: string; verifier: string },
  siteUrl: string,
  issuer: string,
  fetchImpl: typeof fetch = fetch,
  redirectPath = "/settings/",
): Promise<{ did: string; sessionVersion: number; handle?: string }> {
  if (
    !input.code ||
    input.code.length > 2048 ||
    !/^[A-Za-z0-9._~-]{43,128}$/.test(input.verifier)
  ) {
    throw new Error(
      "The connection attempt is invalid. Start again from Settings.",
    );
  }
  const origin = new URL(siteUrl).origin;
  const dpop = await createDpopKeyPair();
  const response = await fetchImpl(`${issuer}/v1/public/token`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    signal: AbortSignal.timeout(15_000),
    body: JSON.stringify({
      code: input.code,
      code_verifier: input.verifier,
      client_id: origin,
      redirect_uri: `${origin}${redirectPath}`,
      dpop_jwk: dpop.publicJwk,
    }),
  });
  if (!response.ok)
    throw new Error(
      "Not Organic could not verify this connection. Start again from Settings.",
    );
  const body = (await response.json()) as { access_token?: string };
  if (typeof body.access_token !== "string" || !body.access_token)
    throw new Error("Not Organic returned no account proof.");
  const accountResponse = await createDpopFetch(
    { accessToken: body.access_token, dpop },
    fetchImpl,
  )(`${issuer}/v1/account`, { signal: AbortSignal.timeout(15_000) });
  if (!accountResponse.ok)
    throw new Error("Not Organic could not verify account ownership.");
  const account = (await accountResponse.json()) as {
    account?: { did?: string; handle?: string | null };
  };
  // This token has now been authenticated by the issuer with its DPoP proof.
  const encoded = body.access_token.split(".")[1];
  const claims = JSON.parse(
    atob(encoded.replace(/-/g, "+").replace(/_/g, "/")),
  ) as { sub?: string; product?: string; session_version?: number };
  if (
    !account.account?.did ||
    !/^did:[a-z0-9]+:[A-Za-z0-9._:%-]+$/.test(account.account.did) ||
    account.account.did !== claims.sub ||
    claims.product !== "twyne" ||
    !Number.isSafeInteger(claims.session_version) ||
    claims.session_version! < 0
  ) {
    throw new Error(
      "The verified account does not match this Twyne connection.",
    );
  }
  const handle = account.account.handle;
  return {
    did: account.account.did,
    sessionVersion: claims.session_version!,
    ...(typeof handle === "string" && handle ? { handle } : {}),
  };
}
